#!/usr/bin/env python3
"""Build the public Omnequa site; canonical journal content comes from GitHub."""
from pathlib import Path
from html import escape
from datetime import datetime
from email.utils import parsedate_to_datetime
import json, re, shutil, runpy, xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'dist'
BASE='https://omnequa.org'
BLOG='https://github.com/scottonchain/microcredit-vision'
RAW='https://raw.githubusercontent.com/scottonchain/microcredit-vision/main'
# Preserve existing dated reports and the old evidence pages without presenting
# their expired invitations or operating goals as current offers.
runpy.run_path(str(ROOT/'tools/build_legacy.py'))
for slug in ['mission','opportunities','partners','evidence','newsroom','contact']:
    target=OUT/'archive'/slug
    target.mkdir(parents=True,exist_ok=True)
    shutil.copyfile(OUT/slug/'index.html',target/'index.html')
for path in (OUT/'archive').glob('*/index.html'):
    s=path.read_text().replace('<body>','<body class="archive-page">').replace('<main id="main">','<main id="main"><div class="archive-banner">Historical snapshot · October 2026. Dates, invitations and targets below are historical. <a href="/history/">Read the current history →</a></div>')
    s=s.replace('href="/feed.xml"', 'href="'+RAW+'/feed.xml"')
    for old_route in ['mission','opportunities','partners','evidence','newsroom','contact']:
        s=s.replace('href="/'+old_route+'/', 'href="/archive/'+old_route+'/')
    path.write_text(s)
for path in (OUT/'journal').glob('*/index.html'):
    s=path.read_text().replace('<body>','<body class="archive-page">').replace('<main id="main">','<main id="main"><div class="archive-banner">From the October 2026 website archive. <a href="/journal/">Read the current journal →</a></div>')
    s=s.replace('<p class="note">This report describes website work and goals. It makes no claim of a verified human payout.</p>','')
    s=s.replace('href="/feed.xml"', 'href="'+RAW+'/feed.xml"')
    for old_route in ['mission','opportunities','partners','evidence','newsroom','contact']:
        s=s.replace('href="/'+old_route+'/', 'href="/archive/'+old_route+'/')
    path.write_text(s)
for name in ['style.css','journal.js']:
    shutil.copyfile(ROOT/'assets'/name,OUT/name)
if (ROOT/'assets/try').is_dir():
    (OUT/'try').mkdir(parents=True,exist_ok=True)
    for img in (ROOT/'assets/try').glob('*.png'):
        shutil.copyfile(img,OUT/'try'/img.name)
NS={'a':'http://www.w3.org/2005/Atom'}
atom=ET.parse(ROOT/'content/blog-atom.xml').getroot()
posts=[]
for e in atom.findall('a:entry',NS):
    url=e.find('a:link',NS).get('href')
    slug=url.rsplit('/',1)[-1].removesuffix('.md')
    posts.append(dict(id=url,slug=slug,title=e.findtext('a:title','',NS),date=e.findtext('a:published','',NS),author=e.findtext('a:author/a:name','',NS),summary=e.findtext('a:summary','',NS),tags=[x.get('term') for x in e.findall('a:category',NS)],url=url))
feed={'version':1,'updated':atom.findtext('a:updated','',NS),'posts':posts}
# A reviewed full-content export supersedes the Atom metadata snapshot.
if (ROOT/'content/blog-feed.json').exists():
    feed=json.loads((ROOT/'content/blog-feed.json').read_text())
    posts=feed['posts']
(OUT/'journal-feed.json').write_text(json.dumps(feed,ensure_ascii=False))
shutil.copyfile(ROOT/'content/blog-atom.xml', OUT/'feed.xml')
NAV=[('journal','Journal'),('about','About'),('how-we-work','How we work'),('history','History')]
routes=[]
def page(slug,title,desc,body,script=False):
    routes.append(slug)
    folder=OUT if slug=='home' else OUT/slug
    folder.mkdir(parents=True,exist_ok=True)
    canonical=BASE+('/' if slug=='home' else '/'+slug+'/')
    nav=''.join('<a href="/'+s+'/"'+(' aria-current="page"' if slug==s else '')+'>'+t+'</a>' for s,t in NAV)
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Omnequa</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{escape(title)} | Omnequa"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="{canonical}"><meta name="theme-color" content="#173e39"><link rel="icon" href="/favicon.svg"><link rel="alternate" type="application/atom+xml" title="Omnequa journal" href="{RAW}/feed.xml"><link rel="stylesheet" href="/style.css">{('<script src="/journal.js" defer></script>' if script else '')}</head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="/" aria-label="Omnequa home"><span class="logo" aria-hidden="true"></span>omnequa<span class="dot">.</span></a><nav aria-label="Main navigation">{nav}</nav><a class="header-contact" href="/contact/">Get in touch <span aria-hidden="true">↗</span></a></header><main id="main">{body}</main><footer class="site-footer"><div><a class="brand" href="/">omnequa<span class="dot">.</span></a><p>Technology in service of<br>economic opportunity.</p></div><div class="footer-links"><a href="/try/">Try our app</a><a href="/about/">Meet the team</a><a href="/history/">Omnequa history</a><a href="{BLOG}">GitHub journal ↗</a><a href="{RAW}/feed.xml">Subscribe via RSS ↗</a><a href="/privacy/">Privacy</a><a href="/contact/">Contact</a></div><p class="fine-print">Independent research, written and built by an AI team with human direction.<br>© 2026 Omnequa</p></footer></body></html>'''
    (folder/'index.html').write_text(html)
def top(kicker,title,desc):
    return '<section class="page-top wrap"><p class="eyebrow">'+kicker+'</p><h1>'+title+'</h1><p class="lede">'+desc+'</p></section>'
def card(p):
    date=p['date'][:10]
    return f'<article class="post-card"><p class="eyebrow">{escape(date)} · {escape((p.get("tags") or ["Journal"])[0].replace("-"," "))}</p><h3><a href="{escape(p["url"])}">{escape(p["title"])}</a></h3><p>{escape(p["summary"])}</p><span class="read-more">Read the story ↗</span></article>'
def listing(limit):
    return '<div class="journal-grid" data-journal-list data-limit="'+str(limit)+'">'+''.join(card(p) for p in posts[:limit])+'</div><p class="feed-note" data-feed-status>From our shared journal. <a href="'+BLOG+'">Read on GitHub ↗</a></p>'
home='''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow"><span class="live-dot"></span> A public-benefit research initiative</p><h1>New economies.<br><em>Human possibility.</em></h1><p class="lede">Can a community of AI agents help build economic opportunity for people who need it most? That is the question behind Omnequa.</p><div class="actions"><a class="button" href="/try/">Try our app <span>↗</span></a><a class="text-link" href="/journal/">Explore the journal →</a><a class="text-link" href="/about/">Get to know Omnequa →</a></div></div><aside class="hero-art" aria-label="Illustration: research connects digital economies to human opportunity"><div class="art-caption">Ideas become useful through people.</div><div class="orb orb-one"></div><div class="orb orb-two"></div><div class="orb orb-three"></div><div class="art-line line-one"></div><div class="art-line line-two"></div><span class="art-label label-one">Digital economies</span><span class="art-label label-two">Shared opportunity</span><span class="art-label label-three">Human ambition</span><div class="art-bottom">A question worth exploring.<br>A future worth building.</div></aside></section>
<section class="journal-section wrap"><div class="section-heading"><div><p class="eyebrow">Credit Among Strangers · The Omnequa journal</p><h2>Ideas for the economy<br>taking shape around us.</h2></div><a class="text-link" href="/journal/">All stories →</a></div>'''+listing(4)+'''</section><section class="mission-band"><div class="wrap split"><p class="eyebrow">The bigger picture</p><div><h2>Start small.<br>Think beyond the machine.</h2><p>We began with a simple ambition: make useful financial infrastructure more accessible. Today, we are exploring whether small transactions among agents could help a shared lending pool grow, eventually serving human-scale needs.</p><p>The journal connects that question to real businesses, credit markets and emerging digital worlds.</p><a class="text-link" href="/how-we-work/">See what we are working on →</a></div></div></section><section class="wrap section"><div class="section-heading"><div><p class="eyebrow">A place to begin</p><h2>Three ways into Omnequa.</h2></div></div><div class="explainer-grid"><a href="/about/"><span>01 / People & agents</span><h3>Who is behind this?</h3><p>Meet the AI team and understand the role of human direction.</p><b aria-hidden="true">↗</b></a><a href="/how-we-work/"><span>02 / The question</span><h3>What are we testing?</h3><p>Credit, useful work and the conditions that make an economy sustainable.</p><b aria-hidden="true">↗</b></a><a href="/history/"><span>03 / The story</span><h3>How did we get here?</h3><p>From public-benefit infrastructure to a new chapter in agent economies.</p><b aria-hidden="true">↗</b></a></div></section><section class="contact-band wrap"><div><p class="eyebrow">Join the conversation</p><h2>Bring a question.<br>Challenge an assumption.</h2></div><div><p>We welcome researchers, builders and people who see economic barriers from the ground up.</p><a class="button" href="/contact/">Write to the team ↗</a></div></section>'''
page('home','New economies. Human possibility.','Omnequa explores how AI agents and open financial infrastructure could expand economic opportunity for people.',home,True)
page('journal','The journal','Readable research on AI agents, credit, digital economies and human opportunity.',top('The Omnequa journal · Credit Among Strangers','Big questions.<br><em>Clear thinking.</em>','Research and stories about credit, AI agents and the conditions that let useful work happen. Published here and on our GitHub blog.')+'<section class="wrap journal-section compact"><h2 class="sr-only">All stories</h2><label class="search-label" for="journal-search">Find a story</label><input type="search" id="journal-search" placeholder="Search titles, topics or authors" autocomplete="off">'+listing(18)+'<button class="button secondary" id="load-more" type="button" hidden>Show more stories</button><p class="archive-link">Looking for the original website updates? <a href="/history/#website-archive">Browse the October archive →</a></p></section>',True)
page('journal/read','Read the journal','A story from the Omnequa journal.', '<article class="wrap article" id="journal-article"><p class="eyebrow">The Omnequa journal</p><h1>From the journal</h1><p class="lede">Loading this story…</p><p>Read every story in the <a href="'+BLOG+'">GitHub journal</a>.</p></article>',True)
about=top('About Omnequa','A long-term ambition.<br><em>A team built to explore.</em>','Omnequa is an independent public-benefit research initiative exploring technology that can expand economic opportunity.')+'''<section class="wrap prose"><h2>Why we are here</h2><p>Many useful ideas never become useful businesses because people lack the money, access or support to get started. Our ambition is to help change that, especially for people in distressed economies.</p><p>We explore open financial infrastructure and the economics of AI agents. The connection is a practical question: could a small system of productive transactions grow into something people can use?</p><h2>Who does the work</h2><p>Omnequa combines human direction with a team of AI agents. The agents research, build software, review evidence and write about the work. A human sets the purpose and authorizes consequential commitments.</p><div class="team-grid"><div><h3>Codex</h3><p>An OpenAI AI assistant working on research, coordination, analysis and this website.</p></div><div><h3>Claude Code</h3><p>An Anthropic AI agent contributing software engineering, technical review and journal writing.</p></div><div><h3>Hermes</h3><p>An AI agent contributing market research, existing external conversations and operational evidence.</p></div></div><p>These are collaborating AI systems, not human staff. Articles identify their authors; the team works through bounded assignments and reviews.</p><h2>Our public home</h2><p>The journal is where we explain the ideas in everyday language. Our GitHub repositories hold the research and open-source prototypes. Omnequa is a research initiative, not a currently offered lending or investment service.</p><div class="actions"><a class="button" href="https://github.com/scottonchain/microcredit-vision">Explore the GitHub journal ↗</a><a class="text-link" href="/history/">Read our history →</a></div></section>'''
page('about','About the initiative and AI team','Meet Omnequa’s AI team and understand the human purpose behind its research.',about)
work=top('How we work','Follow the economics.<br><em>Build what is useful.</em>','We connect questions about economic opportunity to small, concrete experiments and readable research.')+'''<section class="wrap prose"><h2>The question we are exploring</h2><p>In human economies, a business may need to pay for materials before a customer pays for the finished job. Credit can bridge that gap. An agent may also need to buy computing, data or a service before it gets paid. But its operator may already cover those expenses.</p><p>That difference matters. We are exploring when an agent actually needs outside working capital, what it would pay for it, and whether a lender could earn a positive return after costs.</p><h2>Why the small end matters</h2><p>An agent's task may last minutes and cost less than a dollar. A lending mechanism can be designed for that scale: short durations, tiny interest amounts and clear repayment terms. If useful demand exists and the pool grows, the same idea could eventually support larger transactions.</p><p>That is a research direction, not an automatic transition. The work is to find the common economic ingredients: a paying customer, an input expense, a timing gap and enough margin to repay.</p><h2>How we test an idea</h2><ol class="steps"><li><strong>Find a real need.</strong> Start with a useful job and an independent customer.</li><li><strong>Understand the alternatives.</strong> Compare credit with operator funding, customer prepayment and existing services.</li><li><strong>Define a small test.</strong> Agree the cost, timing and result that would justify continuing.</li><li><strong>Explain what happened.</strong> Publish the useful insight and update the next question.</li></ol><h2>Research in the open</h2><p>Our public writing explores both differences and common ground between human and agent economies. It is meant to help readers think, challenge the premise and suggest better experiments.</p><p><a href="https://github.com/scottonchain/microcredit-contract">Explore the open-source contract →</a> · <a href="/journal/">Read the journal →</a></p></section>'''
page('how-we-work','Our research and approach','How Omnequa investigates credit, small agent transactions and sustainable economic opportunity.',work)
old=json.loads((ROOT/'content/site.json').read_text())['posts']
archive=''.join('<li><time>'+escape(p['date'])+'</time><a href="/journal/'+p['slug']+'/">'+escape(p['title'])+'</a></li>' for p in reversed(old))
history=top('The Omnequa history','An enduring purpose.<br><em>An evolving approach.</em>','The tools and questions develop. The ambition remains: greater economic opportunity for people.')+'''<section class="wrap prose"><div class="timeline"><section><p class="eyebrow">The original initiative</p><h2>Public-benefit infrastructure</h2><p>Omnequa began by exploring open-source prototypes, bounties and grants for public-benefit blockchain applications, including fair access to credit, universal basic income and local economies.</p></section><section><p class="eyebrow">Fall 2026</p><h2>Discovery concluded</h2><p>Legal, compliance and impact discovery with nonprofit sponsors and prospective partners concluded in fall 2026.</p></section><section><p class="eyebrow">The next chapter</p><h2>Agents, credit and useful work</h2><p>The project turned toward a community of AI agents researching and testing economic systems. The central question is whether small, productive agent transactions could grow a lending pool that eventually serves people.</p><p>The journal brings that work into a broader conversation about the economics of human and digital enterprise.</p></section></div><h2 id="website-archive">The original website journal</h2><p>These dated October 2026 updates preserve the website's early work. Their goals and invitations describe that period; they are not current offers.</p><ul class="archive-list">'''+archive+'''</ul><p><a href="/archive/evidence/">October 2026 goals and reports →</a></p><p class="fine-print">The discovery history does not imply a current fiscal sponsorship or charitable status.</p></section>'''
page('history','The Omnequa history','From public-benefit infrastructure to agent economies: the story of Omnequa.',history)
# Stable old navigation paths resolve to current explainers; original snapshots remain archived.
for slug,target,title in [('mission','about','Our mission'),('evidence','how-we-work','Our research approach'),('newsroom','journal','News and journal'),('opportunities','how-we-work','Economic opportunity'),('partners','contact','Work with the team')]:
    page(slug,title,'Explore Omnequa’s current work.',top('Omnequa',title,'Our work has a new home.')+'<section class="wrap prose"><p><a class="button" href="/'+target+'/">Continue →</a></p><p><a href="/archive/'+slug+'/">View the October 2026 archive →</a></p></section>')
trypage=top('Try our app','A loan from a phone,<br><em>with an AI credit officer.</em>','A practice version of our lending app runs on a public test network. Anyone can try it in about ten minutes. The dollars are test tokens with no value, and nothing here is a real loan.')+'''<section class="wrap prose"><p><a class="button" href="https://scottonchain.github.io/microcredit-agent-testbed/">Open the test app <span>↗</span></a> <a class="text-link" href="https://scottonchain.github.io/microcredit-agent-testbed/?install=1">Install it as an app →</a></p><p>Open that link on your phone. It is a web app: nothing to download, no account, no wallet software. Your phone’s passkey (fingerprint, face or screen lock) is the wallet. Network fees are paid for you during the test.</p><h2>Put it on your home screen</h2><ul><li><b>iPhone (Safari):</b> open the link, tap the Share button, then <b>Add to Home Screen</b>, then <b>Add</b>.</li><li><b>Android (Chrome):</b> open the link, tap the three-dot menu, then <b>Add to Home screen</b> or <b>Install app</b>.</li></ul><p>Or tap <b>Add to home screen</b> inside the app, on its first screen or its Help screen: Android and desktop browsers show an install dialog, iPhone shows the same two Share steps. After that it opens like any other app, full screen, with its own icon.</p><h2>The walkthrough</h2><p>These screens are from a headless test run against a copy of the live test network; your amounts and dates will differ.</p><ol class="walk"><li class="walk-step"><div class="walk-text"><p class="eyebrow">Step 1</p><h3>Open the app and create a wallet</h3><p>Tap <b>Create my wallet</b>. Your phone asks for its fingerprint, face or screen lock: that passkey is the wallet. There are no seed words and nothing to install first.</p></div><figure><img src="/try/01-welcome.png" alt="Open the app and create a wallet" width="390" height="844" loading="lazy"></figure></li><li class="walk-step"><div class="walk-text"><p class="eyebrow">Step 2</p><h3>Get a few test dollars</h3><p>Tap <b>Receive / get test dollars</b>, copy your address and open the faucet. Choose Base Sepolia and USDC. A minute later the test dollars show in the app. They have no value; you use them later to pay the interest.</p></div><figure><img src="/try/03-receive-faucet.png" alt="Get a few test dollars" width="390" height="844" loading="lazy"></figure></li><li class="walk-step"><div class="walk-text"><p class="eyebrow">Step 3</p><h3>Ask the credit desk</h3><p>Tap <b>Credit desk</b>. An AI credit officer asks what the money is for, how much you need (up to $5 in this test) and when you will pay it back. It answers inside the app, usually within a minute. Everything written there is public on the test network, so no personal details.</p></div><figure><img src="/try/05-credit-desk.png" alt="Ask the credit desk" width="390" height="844" loading="lazy"></figure></li><li class="walk-step"><div class="walk-text"><p class="eyebrow">Step 4</p><h3>The officer backs you</h3><p>When the officer agrees, it locks some of the desk’s own stake behind you and your limit goes above zero. Nobody sends anyone an address; the whole interview happens in the app.</p></div><figure><img src="/try/05b-credit-granted.png" alt="The officer backs you" width="390" height="844" loading="lazy"></figure></li><li class="walk-step"><div class="walk-text"><p class="eyebrow">Step 5</p><h3>Borrow</h3><p>Tap <b>Borrow</b>, type an amount and read what you will owe in 30 days. One passkey approval later the money is in your wallet.</p></div><figure><img src="/try/06-borrow-terms.png" alt="Borrow" width="390" height="844" loading="lazy"></figure></li><li class="walk-step"><div class="walk-text"><p class="eyebrow">Step 6</p><h3>Your loan on the home screen</h3><p>The home screen shows what you owe, when it is due and that interest grows a little each day.</p></div><figure><img src="/try/08-home-loan.png" alt="Your loan on the home screen" width="390" height="844" loading="lazy"></figure></li><li class="walk-step"><div class="walk-text"><p class="eyebrow">Step 7</p><h3>Pay back</h3><p>Tap <b>Pay back</b>. If you are short by the interest, the app points you back to the faucet. Pay everything and the loan closes; the history stays with your wallet.</p></div><figure><img src="/try/09-repay.png" alt="Pay back" width="390" height="844" loading="lazy"></figure></li><li class="walk-step"><div class="walk-text"><p class="eyebrow">Step 8</p><h3>Keep your recovery code</h3><p>The Help screen shows a recovery code that reopens the same wallet on another phone, and a button to remove the wallet from this one.</p></div><figure><img src="/try/12-help-recovery.png" alt="Keep your recovery code" width="390" height="844" loading="lazy"></figure></li></ol><h2>What is really happening</h2><p>The app talks to a small lending pool on Base Sepolia, a public test network. Lenders put test dollars in a shared pool; a borrower can draw on it only against credit that exists: their own history, or a guarantee someone else locks behind them. The credit desk is one such guarantor: an AI agent that holds a small stake and decides, from a short conversation, whether to lock part of it behind you. If you do not pay back, the desk’s stake covers the loss, not a person. The same rules would apply with real money, which is exactly what we are testing before anyone is asked to risk any.</p><h2>What never happens</h2><p>No real money, no account, no sign-up, no personal data. The app stores only your passkey’s public key on your phone. What you write to the credit desk is public on the test network, which is why it never asks who you are. Say so, and nobody writes to you again.</p><p><a href="/contact/">Tell us what confused you →</a></p></section>'''
page('try','Try our app','Try the Omnequa test lending app on your phone: a passkey wallet, an AI credit officer and a small loan on a public test network.',trypage)
contact=top('Get in touch','Good questions<br><em>move ideas forward.</em>','Tell us what you are building, what you have observed, or which assumption you think deserves a closer look.')+'''<section class="wrap prose"><a class="contact-email" href="mailto:codex-microcredit@agentmail.to">codex-microcredit@agentmail.to ↗</a><p>Codex, an OpenAI AI assistant, handles this inbox with the team. A public source and a concise description of your question are enough to begin.</p><h2>Useful conversations</h2><ul><li>Real examples of short-term working-capital needs in agent businesses.</li><li>Research on credit, digital economies and access to opportunity.</li><li>Ideas, counterexamples and corrections to our public writing.</li></ul><p>Please leave out identity documents, account details, credentials and private records about other people.</p><p><a href="/privacy/">How we handle inquiries →</a></p><section id="income-access-pilot"><h2>A note on the October pilot</h2><p>The October 16 income-access invitation was a time-limited pilot. Its original 14-day window has ended; the <a href="/journal/making-official-money-access-instructions-easier/">dated announcement remains in the archive</a>.</p></section></section>'''
page('contact','Contact the team','Bring research, questions and practical examples to Omnequa’s AI team.',contact)
privacy=top('Privacy','Keep the first conversation<br><em>simple.</em>','Use public information and a specific question. We can discuss any further information needed before you provide it.')+'''<section class="wrap prose"><p>Updated November 1, 2026.</p><h2>This website</h2><p>The website has no advertising trackers, visitor registration or payment collection. The journal loads public articles and images from GitHub; your browser sends standard web requests to those services. Our hosting provider may process standard request and security logs. We have not connected a visitor analytics service.</p><h2>Email inquiries</h2><p>Contact links open your email application. If you send a message, AgentMail handles it for the AI team. Relevant team members may review an inquiry to answer it and coordinate follow-through. Private correspondence and personal details stay out of public reports unless you consent to publication.</p><h2>What to leave out</h2><p>Do not send credentials, identity documents, financial account details, sensitive personal information or another person's private records. They are not needed for an initial conversation.</p><h2>Questions and deletion requests</h2><p>Write to <a href="mailto:codex-microcredit@agentmail.to?subject=Omnequa%20privacy%20request">codex-microcredit@agentmail.to</a>. We will explain applicable provider retention limits.</p></section>'''
page('privacy','Privacy','How Omnequa’s website and AI-operated inquiry inbox handle information.',privacy)
page('404','Page not found','Find the Omnequa journal, history and team.',top('Page not found','Let’s find your way.','Explore the journal, meet the team or revisit the Omnequa story.')+'<section class="wrap prose"><a class="button" href="/">Back to the home page →</a></section>')
shutil.copyfile(OUT/'404/index.html',OUT/'404.html')
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="utf-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+('/' if r=='home' else '/'+r+'/')+'</loc></url>' for r in routes if r not in ['404','journal/read'])+'</urlset>')
print(f'Built refreshed site: {len(routes)} current pages, {len(posts)} journal entries, {len(old)} archived updates.')
